Lemma tr_ret_walk : forall (usp : Z) (d1 : byte) (gp t0 t1 t2 s0 s1 v a1 a2 a3 a4 a5 a6 a7 p1 s3 s4 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
